body:
# comment
mixed-port: 7890
proxies:
  - name: 12345
    type: ss
    server: 7.7.7.7
    port: "8388"
    cipher: aes-128-gcm
    password: 0123
  - {name: v2p, type: ss, server: 7.7.7.8, port: 1, cipher: aes-128-gcm, password: p, plugin: v2ray-plugin, plugin-opts: {mode: websocket, host: a.com, path: /x, tls: true}}
  - {name: bad-plugin, type: ss, server: 7.7.7.9, port: 1, cipher: aes-128-gcm, password: p, plugin: shadow-tls}
  - {name: no-port, type: ss, server: 7.7.7.10, cipher: aes-128-gcm, password: p}
  - {name: hy-auth, type: hysteria2, server: h.example.com, port: 443, auth: secret, obfs: salamander, obfs-password: o, alpn: [h3], up: 100, down: "1 Gbps"}
  - {name: grpc, type: vless, server: g.example.com, port: 443, uuid: b831381d-6324-4d53-ad4f-8cda48b30811, tls: true, network: grpc, grpc-opts: {grpc-service-name: svc}, alpn: "h2,http/1.1"}
  - {name: h2, type: vmess, server: h2.example.com, port: 443, uuid: b831381d-6324-4d53-ad4f-8cda48b30811, alterId: 0, cipher: auto, tls: true, network: h2, h2-opts: {path: /h2, host: [h2.example.com]}}
  - {name: http-tls, type: http, server: p.example.com, port: 443, username: u, password: p, tls: true, sni: p.example.com}
  - {name: socks, type: socks5, server: s.example.com, port: 1080}
  - {name: any, type: anytls, server: a.example.com, port: 443, password: p, sni: a.example.com, skip-cert-verify: yes}
  - {name: tuic-alpn, type: tuic, server: t.example.com, port: 443, uuid: b831381d-6324-4d53-ad4f-8cda48b30811, password: p, udp-relay-mode: quic}
  - just a string
proxy-groups:
  - {name: G, proxies: [12345, v2p]}
  - {type: select}
rules:
  - MATCH,G
